                emon.Port.CellsSet(gx, GxStk + (33 + (2 * depth)), -1);
            } else if (c == 125) {
                p += 1;
                if (depth == 0) {
                    return 1;
                }
                depth -= 1;
                sb = emon.Port.CellsAt(gx, GxStk + depth);
                if (sb >= 0) {
                    emon.Port.CellsSet(gx, sb + 1, (emon.Port.CellsAt(gx, GxFnpos) - sb) - 3);
                    lb = emon.Port.CellsAt(gx, GxStk + (33 + (2 * depth)));
                    emon.Port.CellsSet(gx, GxStk + (32 + (2 * depth)), lb);
                    emon.Port.CellsSet(gx, GxStk + (33 + (2 * depth)), sb);
                }
            } else {
                // A word: a number or an operator.
                q = p;
                while ((q < n) && ((GxPsWs(emon.Port.CellsAt(bytes, q)) == 0) && ((emon.Port.CellsAt(bytes, q) != 123) && (emon.Port.CellsAt(bytes, q) != 125)))) {
                    q += 1;
                }
                isnum = 1;
                neg = 0;
                mant = 0;
                digs = 0;
                scale = 0;
                seen = 0;
                prev = p;
                c = emon.Port.CellsAt(bytes, prev);
                if ((c == 45) || (c == 43)) {
                    if (c == 45) {
                        neg = 1;
                    }
                    prev += 1;
                }
                if (prev >= q) {
                    isnum = 0;
                }
                while ((isnum == 1) && (prev < q)) {
                    c = emon.Port.CellsAt(bytes, prev);
                    if ((c >= 48) && (c <= 57)) {
                        if (digs < 9) {
                            mant = (mant * 10) + (c - 48);
                            digs += 1;
                            if (seen == 1) {
                                scale += 1;
                            }
                        } else if (seen == 0) {
                            isnum = 0;
                        }
                    } else if ((c == 46) && (seen == 0)) {
                        seen = 1;
                    } else {
                        isnum = 0;
                    }
                    prev += 1;
                }
                if (isnum == 1) {
                    fv = Fx.FxOfReal(mant, scale);
                    if (neg == 1) {
                        fv = ((long) 0) - fv;
                    }
                    if (GxPsTok(gx, 0, Fx.FxHi(fv), Fx.FxLo(fv)) == 1) {
                        return 1;
                    }
                } else {
                    code = GxPsCode(bytes, p, q - p);
                    if (code == 0) {
                        return 1;
                    }
                    la = emon.Port.CellsAt(gx, GxStk + (32 + (2 * depth)));
                    lb = emon.Port.CellsAt(gx, GxStk + (33 + (2 * depth)));
                    if (code == PsIf) {
                        if (lb < 0) {
                            return 1;
                        }
                        emon.Port.CellsSet(gx, lb, 2);
                        emon.Port.CellsSet(gx, GxStk + (32 + (2 * depth)), -1);
                        emon.Port.CellsSet(gx, GxStk + (33 + (2 * depth)), -1);
                    }
                    if (code == PsIfelse) {
                        if (la < 0) {
                            return 1;
                        }
                        emon.Port.CellsSet(gx, la, 3);
                        emon.Port.CellsSet(gx, lb, 4);
                        emon.Port.CellsSet(gx, GxStk + (32 + (2 * depth)), -1);
                        emon.Port.CellsSet(gx, GxStk + (33 + (2 * depth)), -1);
                    }
                    if ((code != PsIf) && (code != PsIfelse)) {
                        if (GxPsTok(gx, 1, code, 0) == 1) {
                            return 1;
                        }
                    }
                }
                p = q;
            }
        }
        if (depth != 0) {
            return 1;
        }
        return 0;
    }
    internal static int GxPow2(int n) {
        int r = 1;
        int i = 0;
        while (i < n) {
            r *= 2;
            i += 1;
        }
        return r;
    }
    internal static int GxFnCompile(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells gx, int fh, int depth) {
        // Compile the function object `fh` (a dictionary or a stream, resolved) into the function slab at the cursor.
        // Answers the first cell of the compiled function, or -1 (it is not one this module reads, or does not fit).
        if (fh == 0) {
            return -1;
        }
        if (depth > 3) {
            return -1;
        }
        int ftv = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxFunctionType());
        int fty = Pdfx.PxIntOf(ar, ftv, -1);
        int dom = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxDomain());
        int ran = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxRange());
        int nin = GxCount(ar, dom) / 2;
        int nout = GxCount(ar, ran) / 2;
        int f = 0;
        int k = 0;
        int i = 0;
        int j = 0;
        int hasrange = 0;
        int arr = 0;
        int got = 0;
        int cnt = 0;
        int total = 0;
        int bps = 0;
        int el = 0;
        int sub = 0;
        int subf = 0;
        int nbytes = 0;
        int bitpos = 0;
        int val = 0;
        int bit = 0;
        int sz = 0;
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        if ((nin < 1) || (nin > 8)) {
            return -1;
        }
        if (nout > 32) {
            return -1;
        }
        if (nout > 0) {
            hasrange = 1;
        }
        if (fty == 2) {
            arr = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxC0());
            if (arr != 0) {
                nout = GxCount(ar, arr);
            }
            if (arr == 0) {
                nout = 1;
            }
            if ((nout < 1) || (nout > 32)) {
                return -1;
            }
            if (nin != 1) {
                return -1;
            }
        }
        if (fty == 3) {
            if (nin != 1) {
                return -1;
            }
            nout = 0;
        }
        if (((fty == 0) || (fty == 4)) && (hasrange == 0)) {
            return -1;
        }
        if ((fty != 0) && ((fty != 2) && ((fty != 3) && (fty != 4)))) {
            return -1;
        }
        f = GxFnRoom(gx, 5 + ((4 * nin) + (4 * (hasrange * nout))));
        if (f < 0) {
            return -1;
        }
        emon.Port.CellsSet(gx, f, fty);
        emon.Port.CellsSet(gx, f + 1, nin);
        emon.Port.CellsSet(gx, f + 2, nout);
        emon.Port.CellsSet(gx, f + 3, hasrange);
        got = GxReadNums(src, ar, dc, a, b, st, gx, dom, f + 5, 2 * nin);
        if (got < (2 * nin)) {
            return -1;
        }
        if (hasrange == 1) {
            got = GxReadNums(src, ar, dc, a, b, st, gx, ran, f + (5 + (4 * nin)), 2 * nout);
            if (got < (2 * nout)) {
                return -1;
            }
        }
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        // Type 2: C0, C1, N.
        if (fty == 2) {
            total = GxFnRoom(gx, (4 * nout) + 2);
            if (total < 0) {
                return -1;
            }
            arr = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxC0());
            got = GxReadNums(src, ar, dc, a, b, st, gx, arr, total, nout);
            if (got < nout) {
                return -1;
            }
            arr = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxC1());
            if (arr == 0) {
                i = 0;
                while (i < nout) {
                    Fx.FxPut(gx, total + ((2 * nout) + (2 * i)), Fx.FxOne());
                    i += 1;
                }
            } else {
                got = GxReadNums(src, ar, dc, a, b, st, gx, arr, total + (2 * nout), nout);
                if (got < nout) {
                    return -1;
                }
            }
            Fx.FxPut(gx, total + (4 * nout), Fx.FxOne());
            sub = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnN());
            if (Pdfx.PxIsNum(ar, sub) == 0) {
                return -1;
            }
            Fx.FxPut(gx, total + (4 * nout), GxNum(ar, sub));
            emon.Port.CellsSet(gx, f + 4, (total - f) + ((4 * nout) + 2));
            return f;
        }
        // Type 3: Functions, Bounds, Encode.
        if (fty == 3) {
            arr = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxFunctions());
            k = GxCount(ar, arr);
            if ((k < 1) || (k > 32)) {
                return -1;
            }
            total = GxFnRoom(gx, 1 + ((2 * (k - 1)) + ((4 * k) + k)));
            if (total < 0) {
                return -1;
            }
            emon.Port.CellsSet(gx, total, k);
            sub = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxBounds());
            if (k > 1) {
                got = GxReadNums(src, ar, dc, a, b, st, gx, sub, total + 1, k - 1);
                if (got < (k - 1)) {
                    return -1;
                }
            }
            sub = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxEncode());
            got = GxReadNums(src, ar, dc, a, b, st, gx, sub, total + (1 + (2 * (k - 1))), 2 * k);
            if (got < (2 * k)) {
                return -1;
            }
            el = Pdflex.PlFirst(ar, arr);
            i = 0;
            while ((el != 0) && (i < k)) {
                sub = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                if (Pdfsrc.PsMissed(src)) {
                    return -1;
                }
                subf = GxFnCompile(src, ar, dc, a, b, st, @out, gx, sub, depth + 1);
                if (subf < 0) {
                    return -1;
                }
                emon.Port.CellsSet(gx, total + (1 + ((2 * (k - 1)) + ((4 * k) + i))), subf);
                if (i == 0) {
                    emon.Port.CellsSet(gx, f + 2, emon.Port.CellsAt(gx, subf + 2));
                }
                el = Pdflex.PlNext(ar, el);
                i += 1;
            }
            if (i < k) {
                return -1;
            }
            emon.Port.CellsSet(gx, f + 4, emon.Port.CellsAt(gx, GxFnpos) - f);
            return f;
        }
        // Type 0: Size, BitsPerSample, Encode, Decode, the samples.
        if (fty == 0) {
            arr = Pdfdoc.PdDget(src, ar, dc, a, b, st, fh, Pdfnames.PnSize());
            if (GxCount(ar, arr) != nin) {
                return -1;
            }
            sub = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxBitsPerSample());
            bps = Pdfx.PxIntOf(ar, sub, 0);
            if ((bps != 1) && ((bps != 2) && ((bps != 4) && ((bps != 8) && (bps != 16))))) {
                return -1;
            }
            total = GxFnRoom(gx, nin + (1 + ((4 * nin) + ((4 * nout) + 1))));
            if (total < 0) {
                return -1;
            }
            el = Pdflex.PlFirst(ar, arr);
            cnt = 1;
            i = 0;
            while (i < nin) {
                sub = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                sz = Pdfx.PxIntOf(ar, sub, 0);
                if (sz < 1) {
                    return -1;
                }
                if (sz > 65536) {
                    return -1;
                }
                emon.Port.CellsSet(gx, total + i, sz);
                if (cnt > 65536) {
                    return -1;
                }
                cnt *= sz;
                el = Pdflex.PlNext(ar, el);
                i += 1;
            }
            if (cnt > 16384) {
                return -1;
            }
            emon.Port.CellsSet(gx, total + nin, bps);
            sub = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxEncode());
            if (sub == 0) {
                i = 0;
                while (i < nin) {
                    Fx.FxPut(gx, total + (nin + (1 + (4 * i))), (long) 0);
                    Fx.FxPut(gx, total + (nin + (3 + (4 * i))), Fx.FxOfInt(emon.Port.CellsAt(gx, total + i) - 1));
                    i += 1;
                }
            } else {
                got = GxReadNums(src, ar, dc, a, b, st, gx, sub, total + (nin + 1), 2 * nin);
                if (got < (2 * nin)) {
                    return -1;
                }
            }
            sub = Pdfx.PxDget(src, ar, dc, a, b, st, fh, Pdfxnames.PxDecode());
            if (sub == 0) {
                i = 0;
                while (i < (4 * nout)) {
                    emon.Port.CellsSet(gx, total + (nin + (1 + ((4 * nin) + i))), emon.Port.CellsAt(gx, f + (5 + ((4 * nin) + i))));
                    i += 1;
                }
            } else {
                got = GxReadNums(src, ar, dc, a, b, st, gx, sub, total + (nin + (1 + (4 * nin))), 2 * nout);
                if (got < (2 * nout)) {
                    return -1;
                }
            }
            // The samples: cnt * nout of them, one cell each.
            nbytes = cnt * nout;
            Pdfdoc.PdStreamData(src, ar, dc, a, b, st, fh, @out);
            if (Pdfsrc.PsMissed(src)) {
                return -1;
            }
            if (emon.Port.CellsLen(@out) < (((nbytes * bps) + 7) / 8)) {
                return -1;
            }
            emon.Port.CellsSet(gx, total + (nin + (1 + ((4 * nin) + (4 * nout)))), nbytes);
            subf = GxFnRoom(gx, nbytes);
            if (subf < 0) {
                return -1;
            }
            i = 0;
            while (i < nbytes) {
                bitpos = i * bps;
                val = 0;
                j = 0;
                while (j < bps) {
                    bit = (emon.Port.CellsAt(@out, (bitpos + j) / 8) / GxPow2(7 - ((bitpos + j) % 8))) % 2;
                    val = (val * 2) + bit;
                    j += 1;
                }
                emon.Port.CellsSet(gx, subf + i, val);
                i += 1;
            }
            emon.Port.CellsSet(gx, f + 4, emon.Port.CellsAt(gx, GxFnpos) - f);
            return f;
        }
        // Type 4: the calculator.
        Pdfdoc.PdStreamData(src, ar, dc, a, b, st, fh, @out);
        if (Pdfsrc.PsMissed(src)) {
            return -1;
        }
        nbytes = emon.Port.CellsLen(@out);
        total = GxFnRoom(gx, 1);
        if (total < 0) {
            return -1;
        }
        k = emon.Port.CellsAt(gx, GxFnpos);
        if (GxPsCompile(gx, @out, nbytes) == 1) {
            return -1;
        }
        emon.Port.CellsSet(gx, total, emon.Port.CellsAt(gx, GxFnpos) - k);
        emon.Port.CellsSet(gx, f + 4, emon.Port.CellsAt(gx, GxFnpos) - f);
        return f;
    }
    internal static int GxStPush(emon.Port.Cells gx, int tag, long v) {
        int sp = emon.Port.CellsAt(gx, GxSp);
        if (sp >= GxStkmax) {
            emon.Port.CellsSet(gx, GxErr, 1);
            return 1;
        }
        emon.Port.CellsSet(gx, GxStk + (sp * 3), tag);
        Fx.FxPut(gx, GxStk + ((sp * 3) + 1), v);
        emon.Port.CellsSet(gx, GxSp, sp + 1);
        return 0;
    }
    internal static long GxStVal(emon.Port.Cells gx, int i) {
        return Fx.FxGet(gx, GxStk + ((i * 3) + 1));
    }
    internal static int GxStTag(emon.Port.Cells gx, int i) {
        return emon.Port.CellsAt(gx, GxStk + (i * 3));
    }
    internal static int GxStSet(emon.Port.Cells gx, int i, int tag, long v) {
        emon.Port.CellsSet(gx, GxStk + (i * 3), tag);
        Fx.FxPut(gx, GxStk + ((i * 3) + 1), v);
        return 0;
    }
    internal static long GxTrunc(long v) {
        // Toward zero, as an Fx integer.
        if (v >= ((long) 0)) {
            return Fx.FxOfInt(Fx.FxFloor(v));
        }
        return ((long) 0) - Fx.FxOfInt(Fx.FxFloor(((long) 0) - v));
    }
    internal static long GxPow(emon.Port.Cells gx, long x, long n) {
        // x^n by squaring for the integer part and square roots for the fraction (sixteen binary digits); a negative
        // base with a fractional exponent, and 0 to a negative power, are errors.
        long r = Fx.FxOne();
        long @base = Fx.FxAbs(x);
        long en = Fx.FxAbs(n);
        int ip = 0;
        long fp = (long) 0;
        long sq = (long) 0;
        int k = 0;
        int odd = 0;
        if (n == ((long) 0)) {
            return Fx.FxOne();
        }
        ip = Fx.FxFloor(en);
        fp = en - Fx.FxOfInt(ip);
        if ((x < ((long) 0)) && (fp != ((long) 0))) {
            emon.Port.CellsSet(gx, GxErr, 1);
            return (long) 0;
        }
        if ((@base == ((long) 0)) && (n < ((long) 0))) {
            emon.Port.CellsSet(gx, GxErr, 1);
            return (long) 0;
        }
        if (ip > 4096) {
            ip = 4096;
        }
        sq = @base;
        odd = ip % 2;
        while (ip > 0) {
            if ((ip % 2) == 1) {
                r = Fx.FxMul(r, sq);
            }
            sq = Fx.FxMul(sq, sq);
            ip = ip / 2;
        }
        sq = @base;
        while ((k < 16) && (fp > ((long) 0))) {
            sq = Fx.FxSqrt(sq);
            fp = unchecked(fp * ((long) 2));
            if (fp >= Fx.FxOne()) {
                r = Fx.FxMul(r, sq);
                fp -= Fx.FxOne();
            }
            k += 1;
        }
        if ((x < ((long) 0)) && (odd == 1)) {
            r = ((long) 0) - r;
        }
        if (n < ((long) 0)) {
            if (r == ((long) 0)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return (long) 0;
            }
            return Fx.FxDiv(Fx.FxOne(), r);
        }
        return r;
    }
    internal static int GxPsUnary(int op) {
        // 1 for the operators that take one operand.
        if ((op == PsAbs) || ((op == PsNeg) || ((op == PsCeil) || ((op == PsFloor) || (op == PsRound))))) {
            return 1;
        }
        if ((op == PsTrunc) || ((op == PsCvi) || ((op == PsCvr) || ((op == PsSqrt) || (op == PsNot))))) {
            return 1;
        }
        if ((op == PsSin) || ((op == PsCos) || ((op == PsLn) || (op == PsLog)))) {
            return 1;
        }
        return 0;
    }
    internal static int GxPsOp(emon.Port.Cells gx, int op) {
        // One calculator operator on the stack. Answers 0, or 1 and sets GX_ERR (underflow, a division by zero,
        // an operator outside the language).
        int sp = emon.Port.CellsAt(gx, GxSp);
        long x = (long) 0;
        long y = (long) 0;
        long z = (long) 0;
        int tx = 0;
        int ty = 0;
        int res = 0;
        int n = 0;
        int m = 0;
        int ia = 0;
        int ib = 0;
        int w = 0;
        int cd = 0;
        int tag = 0;
        int kk = 0;
        // Stack operators first.
        if (op == PsPop) {
            if (sp < 1) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            emon.Port.CellsSet(gx, GxSp, sp - 1);
            return 0;
        }
        if (op == PsDup) {
            if (sp < 1) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            x = GxStVal(gx, sp - 1);
            tx = GxStTag(gx, sp - 1);
            return GxStPush(gx, tx, x);
        }
        if (op == PsTrue) {
            return GxStPush(gx, 1, Fx.FxOne());
        }
        if (op == PsFalse) {
            return GxStPush(gx, 1, (long) 0);
        }
        if (op == PsExch) {
            if (sp < 2) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            x = GxStVal(gx, sp - 2);
            tx = GxStTag(gx, sp - 2);
            y = GxStVal(gx, sp - 1);
            ty = GxStTag(gx, sp - 1);
            GxStSet(gx, sp - 2, ty, y);
            GxStSet(gx, sp - 1, tx, x);
            return 0;
        }
        if (op == PsCopy) {
            if (sp < 1) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            n = Fx.FxFloor(GxStVal(gx, sp - 1));
            emon.Port.CellsSet(gx, GxSp, sp - 1);
            sp -= 1;
            if ((n < 0) || (n > sp)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            if ((sp + n) > GxStkmax) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            kk = 0;
            while (kk < n) {
                x = GxStVal(gx, (sp - n) + kk);
                tx = GxStTag(gx, (sp - n) + kk);
                GxStPush(gx, tx, x);
                kk += 1;
            }
            return 0;
        }
        if (op == PsIndex) {
            if (sp < 1) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            n = Fx.FxFloor(GxStVal(gx, sp - 1));
            emon.Port.CellsSet(gx, GxSp, sp - 1);
            sp -= 1;
            if ((n < 0) || (n >= sp)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            x = GxStVal(gx, (sp - 1) - n);
            tx = GxStTag(gx, (sp - 1) - n);
            return GxStPush(gx, tx, x);
        }
        if (op == PsRoll) {
            if (sp < 2) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            n = Fx.FxFloor(GxStVal(gx, sp - 2));
            m = Fx.FxFloor(GxStVal(gx, sp - 1));
            emon.Port.CellsSet(gx, GxSp, sp - 2);
            sp -= 2;
            if ((n < 0) || (n > sp)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            if (n == 0) {
                return 0;
            }
            m = m % n;
            if (m < 0) {
                m += n;
            }
            // A positive roll moves the top element under the others, m times.
            while (m > 0) {
                x = GxStVal(gx, sp - 1);
                tx = GxStTag(gx, sp - 1);
                kk = sp - 1;
                while (kk > (sp - n)) {
                    y = GxStVal(gx, kk - 1);
                    ty = GxStTag(gx, kk - 1);
                    GxStSet(gx, kk, ty, y);
                    kk -= 1;
                }
                GxStSet(gx, sp - n, tx, x);
                m -= 1;
            }
            return 0;
        }
        // Unary operators.
        if (GxPsUnary(op) == 1) {
            if (sp < 1) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            x = GxStVal(gx, sp - 1);
            tx = GxStTag(gx, sp - 1);
            z = x;
            tag = 0;
            if (op == PsAbs) {
                z = Fx.FxAbs(x);
            }
            if (op == PsNeg) {
                z = ((long) 0) - x;
            }
            if (op == PsCeil) {
                z = ((long) 0) - Fx.FxOfInt(Fx.FxFloor(((long) 0) - x));
            }
            if (op == PsFloor) {
                z = Fx.FxOfInt(Fx.FxFloor(x));
            }
            if (op == PsRound) {
                z = Fx.FxOfInt(Fx.FxFloor(unchecked(x + (Fx.FxOne() / ((long) 2)))));
            }
            if ((op == PsTrunc) || (op == PsCvi)) {
                z = GxTrunc(x);
            }
            if (op == PsSqrt) {
                if (x < ((long) 0)) {
                    emon.Port.CellsSet(gx, GxErr, 1);
                    return 1;
                }
                z = Fx.FxSqrt(x);
            }
            if ((op == PsSin) || (op == PsCos)) {
                cd = Fx.FxRound(Fx.FxMul(x, Fx.FxOfInt(100))) % 36000;
                if (cd < 0) {
                    cd += 36000;
                }
                if (op == PsSin) {
                    z = Fx.FxSin(cd);
                }
                if (op == PsCos) {
                    z = Fx.FxCos(cd);
                }
            }
            if (op == PsNot) {
                if (tx == 1) {
                    tag = 1;
                    if (x == ((long) 0)) {
                        z = Fx.FxOne();
                    } else {
                        z = (long) 0;
                    }
                } else {
                    ia = Fx.FxFloor(x);
                    z = Fx.FxOfInt((0 - ia) - 1);
                }
            }
            if ((op == PsLn) || (op == PsLog)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            GxStSet(gx, sp - 1, tag, z);
            return 0;
        }
        // Binary operators.
        if (sp < 2) {
            emon.Port.CellsSet(gx, GxErr, 1);
            return 1;
        }
        x = GxStVal(gx, sp - 2);
        tx = GxStTag(gx, sp - 2);
        y = GxStVal(gx, sp - 1);
        ty = GxStTag(gx, sp - 1);
        z = (long) 0;
        tag = 0;
        res = 0;
        if (op == PsAdd) {
            z = Fx.FxClamp(unchecked(x + y));
        }
        if (op == PsSub) {
            z = Fx.FxClamp(x - y);
        }
        if (op == PsMul) {
            z = Fx.FxClamp(Fx.FxMul(x, y));
        }
        if (op == PsDiv) {
            if (y == ((long) 0)) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            z = Fx.FxClamp(Fx.FxDiv(x, y));
        }
        if (op == PsIdiv) {
            ia = Fx.FxFloor(GxTrunc(x));
            ib = Fx.FxFloor(GxTrunc(y));
            if (ib == 0) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            z = Fx.FxOfInt(ia / ib);
        }
        if (op == PsMod) {
            ia = Fx.FxFloor(GxTrunc(x));
            ib = Fx.FxFloor(GxTrunc(y));
            if (ib == 0) {
                emon.Port.CellsSet(gx, GxErr, 1);
                return 1;
            }
            z = Fx.FxOfInt(ia % ib);
        }
        if (op == PsAtan) {
            cd = Fx.FxAtan2(x, y);
            z = Fx.FxMuldiv((long) cd, Fx.FxOne(), (long) 100);
        }
        if (op == PsExp) {
            z = Fx.FxClamp(GxPow(gx, x, y));
            if (emon.Port.CellsAt(gx, GxErr) == 1) {
                return 1;
            }
        }
        if ((op == PsAnd) || ((op == PsOr) || (op == PsXor))) {
            if ((tx == 1) && (ty == 1)) {
                tag = 1;
                ia = 0;
                ib = 0;
                if (x != ((long) 0)) {
                    ia = 1;
                }
                if (y != ((long) 0)) {
                    ib = 1;
                }
                if (op == PsAnd) {
                    w = ia & ib;
                }
                if (op == PsOr) {
                    w = ia | ib;
                }
                if (op == PsXor) {
                    w = ia ^ ib;
                }
                z = Fx.FxOfInt(w);
            } else {
                ia = Fx.FxFloor(x);
                ib = Fx.FxFloor(y);
                if (op == PsAnd) {
                    w = ia & ib;
                }
                if (op == PsOr) {
                    w = ia | ib;
                }
                if (op == PsXor) {
                    w = ia ^ ib;
                }
                z = Fx.FxOfInt(w);
            }
        }
        if (op == PsBitshift) {
            ia = Fx.FxFloor(x);
            ib = Fx.FxFloor(y);
            if (ib > 30) {
                ib = 30;
            }
            if (ib < -30) {
                ib = -30;
            }
            if (ib >= 0) {
                w = ia * GxPow2(ib);
            } else {
                w = ia / GxPow2(0 - ib);
            }
            z = Fx.FxOfInt(w);
        }
        if ((op == PsEq) || ((op == PsNe) || ((op == PsGt) || ((op == PsGe) || ((op == PsLt) || (op == PsLe)))))) {
            tag = 1;
            res = 0;
            if ((op == PsEq) && (x == y)) {
                res = 1;
            }
            if ((op == PsNe) && (x != y)) {
                res = 1;
            }
            if ((op == PsGt) && (x > y)) {
                res = 1;
            }
            if ((op == PsGe) && (x >= y)) {
                res = 1;
            }
            if ((op == PsLt) && (x < y)) {
                res = 1;
            }
            if ((op == PsLe) && (x <= y)) {
                res = 1;
            }
            if (res == 1) {
                z = Fx.FxOne();
            } else {
                z = (long) 0;
            }
        }
        emon.Port.CellsSet(gx, GxSp, sp - 1);
        GxStSet(gx, sp - 2, tag, z);
        return 0;
    }
    internal static int GxPsRun(emon.Port.Cells gx, int prog, int end) {
        int pc = prog;
        int kind = 0;
        int av = 0;
        int sp = 0;
        long cv = (long) 0;
        while ((pc < end) && (emon.Port.CellsAt(gx, GxErr) == 0)) {
            kind = emon.Port.CellsAt(gx, pc);
            av = emon.Port.CellsAt(gx, pc + 1);
            if (kind == 0) {
                GxStPush(gx, 0, Fx.FxJoin(emon.Port.CellsAt(gx, pc + 1), emon.Port.CellsAt(gx, pc + 2)));
                pc += 3;
            }
            if (kind == 1) {
                GxPsOp(gx, av);
                pc += 3;
            }
            if ((kind == 2) || (kind == 3)) {
                sp = emon.Port.CellsAt(gx, GxSp);
                if (sp < 1) {
                    emon.Port.CellsSet(gx, GxErr, 1);
                } else {
                    cv = GxStVal(gx, sp - 1);
                    emon.Port.CellsSet(gx, GxSp, sp - 1);
                    if (cv != ((long) 0)) {
                        pc += 3;
                    } else {
                        if (kind == 2) {
                            pc += 3 + av;
                        }
                        if (kind == 3) {
                            pc += 6 + av;
                        }
                    }
                }
            }
            if (kind == 4) {
                pc += 3 + av;
            }
            if (kind == 5) {
                emon.Port.CellsSet(gx, GxErr, 1);
            }
        }
        if (emon.Port.CellsAt(gx, GxErr) == 1) {
            return 1;
        }
        return 0;
    }
    internal static int GxClipRange(emon.Port.Cells gx, int f, int nout) {
        // Clip the outputs to the function's /Range when it has one.
        if (emon.Port.CellsAt(gx, f + 3) == 0) {
            return 0;
        }
        int rbase = f + (5 + (4 * emon.Port.CellsAt(gx, f + 1)));
        int j = 0;
        long v = (long) 0;
        long lo = (long) 0;
        long hi = (long) 0;
        while (j < nout) {
            v = Fx.FxGet(gx, GxOut + (2 * j));
            lo = Fx.FxGet(gx, rbase + (4 * j));
            hi = Fx.FxGet(gx, rbase + ((4 * j) + 2));
            if (v < lo) {
                v = lo;
            }
            if (v > hi) {
                v = hi;
            }
            Fx.FxPut(gx, GxOut + (2 * j), v);
            j += 1;
        }
        return 0;
    }
    internal static int GxFnEval(emon.Port.Cells gx, int f) {
        // Run the compiled function at f on the inputs at GX_IN (Fx): the outputs are at GX_OUT. Answers the number of
        // outputs, or -1 (GX_ERR is set). The caller has cleared GX_ERR.
        int fty = emon.Port.CellsAt(gx, f);
        int nin = emon.Port.CellsAt(gx, f + 1);
        int nout = emon.Port.CellsAt(gx, f + 2);
        int dbase = f + 5;
        int body = f + (5 + ((4 * nin) + (4 * (emon.Port.CellsAt(gx, f + 3) * nout))));
        int i = 0;
        int j = 0;
        long x = (long) 0;
        long lo = (long) 0;
        long hi = (long) 0;
        long y = (long) 0;
        long y1 = (long) 0;
        long e = (long) 0;
        long xn = (long) 0;
        int k = 0;
        int sub = 0;
        int sz = 0;
        int idx = 0;
        int stride = 0;
        int i0 = 0;
        int i1 = 0;
        int bps = 0;
        int sbase = 0;
        int ebase = 0;
        int cb = 0;
        int got = 0;
        long fr = (long) 0;
        long dlo = (long) 0;
        long dhi = (long) 0;
        int plen = 0;
        // Clip every input to its domain.
        while (i < nin) {
            x = Fx.FxGet(gx, GxIn + (2 * i));
            lo = Fx.FxGet(gx, dbase + (4 * i));
            hi = Fx.FxGet(gx, dbase + ((4 * i) + 2));
            if (x < lo) {
                x = lo;
            }
            if (x > hi) {
                x = hi;
            }
            Fx.FxPut(gx, GxIn + (2 * i), x);
            i += 1;
        }
        if (fty == 2) {
            x = Fx.FxGet(gx, GxIn);
            y = Fx.FxGet(gx, body + (4 * nout));
            xn = GxPow(gx, x, y);
            if (emon.Port.CellsAt(gx, GxErr) == 1) {
                return -1;
            }
            j = 0;
            while (j < nout) {
                y = Fx.FxGet(gx, body + (2 * j));
                y1 = Fx.FxGet(gx, body + ((2 * nout) + (2 * j)));
                Fx.FxPut(gx, GxOut + (2 * j), Fx.FxClamp(unchecked(y + Fx.FxMul(xn, y1 - y))));
                j += 1;
            }
            GxClipRange(gx, f, nout);
            return nout;
        }
        if (fty == 3) {
            k = emon.Port.CellsAt(gx, body);
            x = Fx.FxGet(gx, GxIn);
            lo = Fx.FxGet(gx, dbase);
            hi = Fx.FxGet(gx, dbase + 2);
            // The sub-domain x lies in: the number of bounds <= x, but not past the last.
            i = 0;
            while ((i < (k - 1)) && (x >= Fx.FxGet(gx, body + (1 + (2 * i))))) {
                i += 1;
            }
            dlo = lo;
            if (i > 0) {
                dlo = Fx.FxGet(gx, body + (1 + (2 * (i - 1))));
            }
            dhi = hi;
            if (i < (k - 1)) {
                dhi = Fx.FxGet(gx, body + (1 + (2 * i)));
            }
            ebase = body + (1 + (2 * (k - 1)));
            y = Fx.FxGet(gx, ebase + (4 * i));
            y1 = Fx.FxGet(gx, ebase + ((4 * i) + 2));
            if (dhi == dlo) {
                e = y;
            } else {
                e = Fx.FxClamp(unchecked(y + Fx.FxMuldiv(x - dlo, y1 - y, dhi - dlo)));
            }
            Fx.FxPut(gx, GxIn, e);
            sub = emon.Port.CellsAt(gx, ebase + ((4 * k) + i));
            got = GxFnEval(gx, sub);
            if (got < 0) {
                return -1;
            }
            GxClipRange(gx, f, got);
            return got;
        }
        if (fty == 0) {
            bps = emon.Port.CellsAt(gx, body + nin);
            ebase = body + (nin + 1);
            cb = ebase + (4 * nin);
            sbase = cb + ((4 * nout) + 1);
            // Encode each input into sample coordinates, clamped to [0, size-1].
            if (nin == 1) {
                sz = emon.Port.CellsAt(gx, body);
                x = Fx.FxGet(gx, GxIn);
                lo = Fx.FxGet(gx, dbase);
                hi = Fx.FxGet(gx, dbase + 2);
                dlo = Fx.FxGet(gx, ebase);
                dhi = Fx.FxGet(gx, ebase + 2);
                if (hi == lo) {
                    e = dlo;
                } else {
                    e = Fx.FxClamp(unchecked(dlo + Fx.FxMuldiv(x - lo, dhi - dlo, hi - lo)));
                }
                if (e < ((long) 0)) {
                    e = (long) 0;
                }
                if (e > Fx.FxOfInt(sz - 1)) {
                    e = Fx.FxOfInt(sz - 1);
                }
                i0 = Fx.FxFloor(e);
                fr = e - Fx.FxOfInt(i0);
                i1 = i0;
                if ((i0 + 1) < sz) {
                    i1 = i0 + 1;
                }
                j = 0;
                while (j < nout) {
                    y = Fx.FxOfInt(emon.Port.CellsAt(gx, sbase + ((i0 * nout) + j)));
                    y1 = Fx.FxOfInt(emon.Port.CellsAt(gx, sbase + ((i1 * nout) + j)));
                    y = Fx.FxClamp(unchecked(y + Fx.FxMul(fr, y1 - y)));
                    dlo = Fx.FxGet(gx, cb + (4 * j));
                    dhi = Fx.FxGet(gx, cb + ((4 * j) + 2));
                    Fx.FxPut(gx, GxOut + (2 * j), Fx.FxClamp(unchecked(dlo + Fx.FxMuldiv(y, dhi - dlo, Fx.FxOfInt(GxPow2(bps) - 1)))));
                    j += 1;
                }
            } else {
                idx = 0;
                stride = 1;
                i = 0;
                while (i < nin) {
                    sz = emon.Port.CellsAt(gx, body + i);
                    x = Fx.FxGet(gx, GxIn + (2 * i));
                    lo = Fx.FxGet(gx, dbase + (4 * i));
                    hi = Fx.FxGet(gx, dbase + ((4 * i) + 2));
                    dlo = Fx.FxGet(gx, ebase + (4 * i));
                    dhi = Fx.FxGet(gx, ebase + ((4 * i) + 2));
                    if (hi == lo) {
                        e = dlo;
                    } else {
                        e = Fx.FxClamp(unchecked(dlo + Fx.FxMuldiv(x - lo, dhi - dlo, hi - lo)));
                    }
                    i0 = Fx.FxRound(e);
                    if (i0 < 0) {
                        i0 = 0;
                    }
                    if (i0 > (sz - 1)) {
                        i0 = sz - 1;
                    }
                    idx += i0 * stride;
                    stride *= sz;
                    i += 1;
                }
                j = 0;
                while (j < nout) {
                    y = Fx.FxOfInt(emon.Port.CellsAt(gx, sbase + ((idx * nout) + j)));
                    dlo = Fx.FxGet(gx, cb + (4 * j));
                    dhi = Fx.FxGet(gx, cb + ((4 * j) + 2));
                    Fx.FxPut(gx, GxOut + (2 * j), Fx.FxClamp(unchecked(dlo + Fx.FxMuldiv(y, dhi - dlo, Fx.FxOfInt(GxPow2(bps) - 1)))));
                    j += 1;
                }
            }
            GxClipRange(gx, f, nout);
            return nout;
        }
        if (fty == 4) {
            plen = emon.Port.CellsAt(gx, body);
            emon.Port.CellsSet(gx, GxSp, 0);
            i = 0;
            while (i < nin) {
                x = Fx.FxGet(gx, GxIn + (2 * i));
                GxStPush(gx, 0, x);
                i += 1;
            }
            if (GxPsRun(gx, body + 1, (body + 1) + plen) == 1) {
                return -1;
            }
            k = emon.Port.CellsAt(gx, GxSp);
            if (k < nout) {
                return -1;
            }
            j = 0;
            while (j < nout) {
                x = GxStVal(gx, (k - nout) + j);
                Fx.FxPut(gx, GxOut + (2 * j), x);
                j += 1;
            }
            GxClipRange(gx, f, nout);
            return nout;
        }
        return -1;
    }
    internal static int GxFnRun(emon.Port.Cells gx, int f) {
        // `gx-fn-eval` from a clean error flag.
        emon.Port.CellsSet(gx, GxErr, 0);
        return GxFnEval(gx, f);
    }
    internal const int CsFnat = 17;
    internal const int CsHival = 18;
    internal static int GxFind(emon.Port.Cells gx, int key) {
        // The table entry whose key is `key`, or -1.
        int i = 0;
        while (i < GxNent) {
            if (emon.Port.CellsAt(gx, GxE(i, CsKey)) == key) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int GxAlloc(emon.Port.Cells gx, int key) {
        // A fresh entry for `key`, replacing the oldest of the cache (the permanent four never go).
        int e = emon.Port.CellsAt(gx, GxRr);
        int j = 0;
        if ((e < 4) || (e >= GxNent)) {
            e = 4;
        }
        emon.Port.CellsSet(gx, GxRr, e + 1);
        while (j < Csd) {
            emon.Port.CellsSet(gx, GxE(e, j), 0);
            j += 1;
        }
        emon.Port.CellsSet(gx, GxE(e, CsKey), key);
        emon.Port.CellsSet(gx, GxE(e, CsInit), -1);
        emon.Port.CellsSet(gx, GxE(e, CsXw), 96420);
        emon.Port.CellsSet(gx, GxE(e, CsYw), 100000);
        emon.Port.CellsSet(gx, GxE(e, CsZw), 82490);
        emon.Port.CellsSet(gx, GxE(e, CsAmin), -100);
        emon.Port.CellsSet(gx, GxE(e, CsAmax), 100);
        emon.Port.CellsSet(gx, GxE(e, CsBmin), -100);
        emon.Port.CellsSet(gx, GxE(e, CsBmax), 100);
        return e;
    }
    internal static int GxPalAt(emon.Port.Cells gx, int e, int i) {
        return emon.Port.CellsAt(gx, GxPal + ((e * 256) + i));
    }
    public static int GxEntryRgb(emon.Port.Cells gx, int e, int n) {
        // The colour whose n components are at GX_IN (Fx), in the space of entry e, as 0xRRGGBB; -1 when it is not
        // known (a pattern, a function that cannot run, a space that was not read).
        int kind = emon.Port.CellsAt(gx, GxE(e, CsKind));
        int model = emon.Port.CellsAt(gx, GxE(e, CsModel));
        int j = 0;
        int idx = 0;
        int nout = 0;
        long t = (long) 0;
        if (kind == 0) {
            return -1;
        }
        if (kind == CkPattern) {
            return -1;
        }
        // Components the operator did not give are 0.
        j = n;
        while (j < 4) {
            Fx.FxPut(gx, GxIn + (2 * j), (long) 0);
            j += 1;
        }
        if (kind == CkIndexed) {
            idx = Fx.FxRound(Fx.FxGet(gx, GxIn));
            if (idx < 0) {
                idx = 0;
            }
            if (idx >= emon.Port.CellsAt(gx, GxE(e, CsNpal))) {
                idx = emon.Port.CellsAt(gx, GxE(e, CsNpal)) - 1;
            }
            if (idx < 0) {
                return -1;
            }
            return GxPalAt(gx, e, idx);
        }
        if (kind == CkSep) {
            if (emon.Port.CellsAt(gx, GxE(e, CsPal)) == 0) {
                return -1;
            }
            t = GxUnit(Fx.FxGet(gx, GxIn));
            return GxPalAt(gx, e, GxByte(t));
        }
        if (kind == CkDevn) {
            if (emon.Port.CellsAt(gx, GxE(e, CsFn)) == 0) {
                return -1;
            }
            nout = GxFnRun(gx, emon.Port.CellsAt(gx, GxE(e, CsFnat)));
            if (nout < 0) {
                return -1;
            }
            j = nout;
            while (j < 4) {
                Fx.FxPut(gx, GxOut + (2 * j), (long) 0);
                j += 1;
            }
            return GxModelRgb(gx, e, model, GxOut);
        }
        return GxModelRgb(gx, e, model, GxIn);
    }
    internal static int GxModelOf(emon.Port.Cells gx, int e) {
        // The colour model (1 gray, 2 rgb, 3 cmyk, 6 lab) an alternate space converts its components with, or 0 for a
        // space that cannot be an alternate.
        int kind = emon.Port.CellsAt(gx, GxE(e, CsKind));
        if ((kind == CkIndexed) || ((kind == CkSep) || ((kind == CkDevn) || ((kind == CkPattern) || (kind == 0))))) {
            return 0;
        }
        return emon.Port.CellsAt(gx, GxE(e, CsModel));
    }
    public static int GxKeyOf(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int h) {
        // The key of a colour space object (resolved): -1 DeviceGray, -2 DeviceRGB, -3 DeviceCMYK, -4 Pattern, else its
        // own handle for a space that is an array; 0 for what is no colour space.
        if (h == 0) {
            return 0;
        }
        int kind = Pdflex.PlKindOf(ar, h);
        int n0 = 0;
        if (kind == 4) {
            if ((Pdflex.PlNameIs(ar, h, Pdfnames.PnDeviceGray()) == 1) || (Pdfx.PxIs(ar, h, Pdfxnames.PxG()) == 1)) {
                return -1;
            }
            if ((Pdflex.PlNameIs(ar, h, Pdfnames.PnDeviceRgb()) == 1) || (Pdfx.PxIs(ar, h, Pdfxnames.PxRgb()) == 1)) {
                return -2;
            }
            if ((Pdflex.PlNameIs(ar, h, Pdfnames.PnDeviceCmyk()) == 1) || (Pdfx.PxIs(ar, h, Pdfxnames.PxCmyk()) == 1)) {
                return -3;
            }
            if (Pdflex.PlNameIs(ar, h, Pdfnames.PnPattern()) == 1) {
                return -4;
            }
            return 0;
        }
        if (kind == 6) {
            n0 = Pdflex.PlFirst(ar, h);
            if (n0 == 0) {
                return 0;
            }
            n0 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, n0);
            if (n0 == 0) {
                return 0;
            }
            if (Pdflex.PlKindOf(ar, n0) == 4) {
                if (Pdflex.PlNameIs(ar, n0, Pdfnames.PnPattern()) == 1) {
                    return -4;
                }
                if (Pdflex.PlNameIs(ar, n0, Pdfnames.PnDeviceGray()) == 1) {
                    return -1;
                }
                if (Pdflex.PlNameIs(ar, n0, Pdfnames.PnDeviceRgb()) == 1) {
                    return -2;
                }
                if (Pdflex.PlNameIs(ar, n0, Pdfnames.PnDeviceCmyk()) == 1) {
                    return -3;
                }
            }
            return h;
        }
        return 0;
    }
    internal static int GxSetLabParams(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells gx, int e, int dict) {
        // Lab's /WhitePoint and /Range (and CalRGB's white point, which is unused) from the dictionary.
        int wp = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxWhitePoint());
        int rg = Pdfx.PxDget(src, ar, dc, a, b, st, dict, Pdfxnames.PxRange());
        int got = 0;
        long w0 = (long) 0;
        long w1 = (long) 0;
        long w2 = (long) 0;
        long w3 = (long) 0;
        if (GxCount(ar, wp) != 0) {
            got = GxReadNums(src, ar, dc, a, b, st, gx, wp, GxOut + 20, 3);
            if (got == 3) {
                w0 = Fx.FxGet(gx, GxOut + 20);
                w1 = Fx.FxGet(gx, GxOut + 22);
                w2 = Fx.FxGet(gx, GxOut + 24);
                emon.Port.CellsSet(gx, GxE(e, CsXw), Fx.FxRound(Fx.FxMul(w0, Fx.FxOfInt(100000))));
                emon.Port.CellsSet(gx, GxE(e, CsYw), Fx.FxRound(Fx.FxMul(w1, Fx.FxOfInt(100000))));
                emon.Port.CellsSet(gx, GxE(e, CsZw), Fx.FxRound(Fx.FxMul(w2, Fx.FxOfInt(100000))));
            }
        }
        if (GxCount(ar, rg) != 0) {
            got = GxReadNums(src, ar, dc, a, b, st, gx, rg, GxOut + 20, 4);
            if (got == 4) {
                w0 = Fx.FxGet(gx, GxOut + 20);
                w1 = Fx.FxGet(gx, GxOut + 22);
                w2 = Fx.FxGet(gx, GxOut + 24);
                w3 = Fx.FxGet(gx, GxOut + 26);
                emon.Port.CellsSet(gx, GxE(e, CsAmin), Fx.FxRound(w0));
                emon.Port.CellsSet(gx, GxE(e, CsAmax), Fx.FxRound(w1));
                emon.Port.CellsSet(gx, GxE(e, CsBmin), Fx.FxRound(w2));
                emon.Port.CellsSet(gx, GxE(e, CsBmax), Fx.FxRound(w3));
            }
        }
        return 0;
    }
    internal static int GxCopyModel(emon.Port.Cells gx, int dst, int srce) {
        // Give entry dst the colour model of entry srce, with Lab's white point and range.
        int mo = GxModelOf(gx, srce);
        emon.Port.CellsSet(gx, GxE(dst, CsModel), mo);
        emon.Port.CellsSet(gx, GxE(dst, CsXw), emon.Port.CellsAt(gx, GxE(srce, CsXw)));
        emon.Port.CellsSet(gx, GxE(dst, CsYw), emon.Port.CellsAt(gx, GxE(srce, CsYw)));
        emon.Port.CellsSet(gx, GxE(dst, CsZw), emon.Port.CellsAt(gx, GxE(srce, CsZw)));
        emon.Port.CellsSet(gx, GxE(dst, CsAmin), emon.Port.CellsAt(gx, GxE(srce, CsAmin)));
        emon.Port.CellsSet(gx, GxE(dst, CsAmax), emon.Port.CellsAt(gx, GxE(srce, CsAmax)));
        emon.Port.CellsSet(gx, GxE(dst, CsBmin), emon.Port.CellsAt(gx, GxE(srce, CsBmin)));
        emon.Port.CellsSet(gx, GxE(dst, CsBmax), emon.Port.CellsAt(gx, GxE(srce, CsBmax)));
        return 0;
    }
    internal static int GxTint(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells gx, int e, int arr, int ncomp) {
        // Separation and DeviceN: the alternate space is element 2 of `arr`, the tint transform element 3. Fills the
        // entry's colour model from the alternate and compiles the transform into its function slab. Answers 1 when
        // both worked.
        int aeh = Pdfx.PxNth(ar, arr, 2);
        int feh = Pdfx.PxNth(ar, arr, 3);
        int ah = Pdfdoc.PdResolve(src, ar, dc, a, b, st, aeh);
        int fh = Pdfdoc.PdResolve(src, ar, dc, a, b, st, feh);
        int ak = 0;
        int ae = -1;
        int at = 0;
        int ff = -1;
        if (Pdfsrc.PsMissed(src)) {
            return 0;
        }
        ak = GxKeyOf(src, ar, dc, a, b, st, ah);
        if (ak == 0) {
            return 0;
        }
        ae = GxLookup(src, ar, dc, a, b, st, @out, gx, ak);
        if (ae < 0) {
            return 0;
        }
        if (GxModelOf(gx, ae) == 0) {
            return 0;
        }
        GxCopyModel(gx, e, ae);
        at = GxFn + (e * FnSlab);
        emon.Port.CellsSet(gx, GxFnpos, at);
        emon.Port.CellsSet(gx, GxFnlim, at + FnSlab);
        emon.Port.CellsSet(gx, GxFail, 0);
        ff = GxFnCompile(src, ar, dc, a, b, st, @out, gx, fh, 0);
        if (Pdfsrc.PsMissed(src)) {
            return 0;
        }
        if ((ff < 0) || (emon.Port.CellsAt(gx, GxFail) == 1)) {
            return 0;
        }
        if (emon.Port.CellsAt(gx, ff + 1) != ncomp) {
            return 0;
        }
        emon.Port.CellsSet(gx, GxE(e, CsFn), 1);
        emon.Port.CellsSet(gx, GxE(e, CsFnat), ff);
        return 1;
    }
    internal static int GxParse(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells gx, int e, int h) {
        // Fill table entry e from the colour space array h (resolved). Leaves the kind 0 (unreadable) when it is not
        // one this module reads.
        int f0 = Pdflex.PlFirst(ar, h);
        int e1 = Pdfx.PxNth(ar, h, 1);
        int n0 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, f0);
        int d1 = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e1);
        int n = 0;
        int i = 0;
        int j = 0;
        int bk = 0;
        int be = -1;
        int hival = 0;
        int nb = 0;
        int lk = 0;
        int ll = 0;
        int bv = 0;
        int ok = 0;
        int allnone = 0;
        int el = 0;
        int rv = 0;
        long cv = (long) 0;
        int pcol = 0;
        int mo = 0;
        int lh = 0;
        if (Pdfsrc.PsMissed(src)) {
            return 0;
        }
        if (n0 == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, n0) != 4) {
            return 0;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxCalGray()) == 1) {
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkCalgray);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), 1);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsGray);
            emon.Port.CellsSet(gx, GxE(e, CsModel), 1);
            emon.Port.CellsSet(gx, GxE(e, CsInit), 0);
            return 1;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxCalRgb()) == 1) {
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkCalrgb);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), 3);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsRgb);
            emon.Port.CellsSet(gx, GxE(e, CsModel), 2);
            emon.Port.CellsSet(gx, GxE(e, CsInit), 0);
            return 1;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxLab()) == 1) {
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkLab);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), 3);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsOther);
            emon.Port.CellsSet(gx, GxE(e, CsModel), 6);
            emon.Port.CellsSet(gx, GxE(e, CsInit), 0);
            if (d1 != 0) {
                GxSetLabParams(src, ar, dc, a, b, st, gx, e, d1);
            }
            return 1;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxIccBased()) == 1) {
            if (d1 == 0) {
                return 0;
            }
            rv = Pdfdoc.PdDget(src, ar, dc, a, b, st, d1, Pdfnames.PnN());
            n = Pdfx.PxIntOf(ar, rv, 0);
            if ((n != 1) && ((n != 3) && (n != 4))) {
                return 0;
            }
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkIcc);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), n);
            if (n == 1) {
                emon.Port.CellsSet(gx, GxE(e, CsClass), ClsGray);
                emon.Port.CellsSet(gx, GxE(e, CsModel), 1);
            }
            if (n == 3) {
                emon.Port.CellsSet(gx, GxE(e, CsClass), ClsRgb);
                emon.Port.CellsSet(gx, GxE(e, CsModel), 2);
            }
            if (n == 4) {
                emon.Port.CellsSet(gx, GxE(e, CsClass), ClsCmyk);
                emon.Port.CellsSet(gx, GxE(e, CsModel), 3);
            }
            emon.Port.CellsSet(gx, GxE(e, CsInit), 0);
            return 1;
        }
        if ((Pdfx.PxIs(ar, n0, Pdfxnames.PxIndexed()) == 1) || (Pdfx.PxIs(ar, n0, Pdfxnames.PxI()) == 1)) {
            rv = Pdfx.PxNth(ar, h, 1);
            rv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, rv);
            bk = GxKeyOf(src, ar, dc, a, b, st, rv);
            if ((bk == 0) || (bk == -4)) {
                return 0;
            }
            be = GxLookup(src, ar, dc, a, b, st, @out, gx, bk);
            if (be < 0) {
                return 0;
            }
            if (GxKind(gx, be) == CkIndexed) {
                return 0;
            }
            nb = GxNcomp(gx, be);
            rv = Pdfx.PxNth(ar, h, 2);
            rv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, rv);
            hival = Pdfx.PxIntOf(ar, rv, -1);
            if ((hival < 0) || (hival > 255)) {
                return 0;
            }
            rv = Pdfx.PxNth(ar, h, 3);
            rv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, rv);
            if (Pdfsrc.PsMissed(src)) {
                return 0;
            }
            if (rv == 0) {
                return 0;
            }
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkIndexed);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), 1);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsOther);
            emon.Port.CellsSet(gx, GxE(e, CsNpal), hival + 1);
            emon.Port.CellsSet(gx, GxE(e, CsHival), hival);
            // The lookup table: a string, or a stream.
            lk = 0;
            if (Pdflex.PlKindOf(ar, rv) == 5) {
                lk = 1;
            }
            if (Pdflex.PlKindOf(ar, rv) == 8) {
                lk = 2;
                Pdfdoc.PdStreamData(src, ar, dc, a, b, st, rv, @out);
                if (Pdfsrc.PsMissed(src)) {
                    return 0;
                }
            }
            if (lk == 0) {
                return 0;
            }
            if (lk == 1) {
                ll = Pdflex.PlStrLen(ar, rv);
            } else {
                ll = emon.Port.CellsLen(@out);
            }
            i = 0;
            while (i <= hival) {
                j = 0;
                while (j < nb) {
                    bv = 0;
                    if (((i * nb) + j) < ll) {
                        if (lk == 1) {
                            bv = Pdflex.PlStrByte(ar, rv, (i * nb) + j);
                        }
                        if (lk == 2) {
                            bv = emon.Port.CellsAt(@out, (i * nb) + j);
                        }
                    }
                    cv = Fx.FxDiv(Fx.FxOfInt(bv), Fx.FxOfInt(255));
                    // A Lab base's components have their own ranges.
                    if (GxKind(gx, be) == CkLab) {
                        if (j == 0) {
                            cv = Fx.FxMul(cv, Fx.FxOfInt(100));
                        }
                        if (j == 1) {
                            cv = unchecked(Fx.FxOfInt(emon.Port.CellsAt(gx, GxE(be, CsAmin))) + Fx.FxMul(cv, Fx.FxOfInt(emon.Port.CellsAt(gx, GxE(be, CsAmax)) - emon.Port.CellsAt(gx, GxE(be, CsAmin)))));
                        }
                        if (j == 2) {
                            cv = unchecked(Fx.FxOfInt(emon.Port.CellsAt(gx, GxE(be, CsBmin))) + Fx.FxMul(cv, Fx.FxOfInt(emon.Port.CellsAt(gx, GxE(be, CsBmax)) - emon.Port.CellsAt(gx, GxE(be, CsBmin)))));
                        }
                    }
                    Fx.FxPut(gx, GxIn + (2 * j), cv);
                    j += 1;
                }
                pcol = GxEntryRgb(gx, be, nb);
                emon.Port.CellsSet(gx, GxPal + ((e * 256) + i), pcol);
                i += 1;
            }
            emon.Port.CellsSet(gx, GxE(e, CsPal), 1);
            pcol = GxPalAt(gx, e, 0);
            emon.Port.CellsSet(gx, GxE(e, CsInit), pcol);
            return 1;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxSeparation()) == 1) {
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkSep);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), 1);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsSpot);
            el = Pdfx.PxNth(ar, h, 1);
            rv = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
            if (Pdfx.PxIs(ar, rv, Pdfxnames.PxNone()) == 1) {
                emon.Port.CellsSet(gx, GxE(e, CsNone), 1);
            }
            ok = GxTint(src, ar, dc, a, b, st, @out, gx, e, h, 1);
            if (Pdfsrc.PsMissed(src)) {
                return 0;
            }
            if (ok == 0) {
                return 1;
            }
            // The 256 colours of tints 0, 1/255 ... 1.
            i = 0;
            while (i < 256) {
                Fx.FxPut(gx, GxIn, Fx.FxDiv(Fx.FxOfInt(i), Fx.FxOfInt(255)));
                pcol = -1;
                lh = GxFnRun(gx, emon.Port.CellsAt(gx, GxE(e, CsFnat)));
                if (lh >= 0) {
                    j = lh;
                    while (j < 4) {
                        Fx.FxPut(gx, GxOut + (2 * j), (long) 0);
                        j += 1;
                    }
                    mo = emon.Port.CellsAt(gx, GxE(e, CsModel));
                    pcol = GxModelRgb(gx, e, mo, GxOut);
                }
                emon.Port.CellsSet(gx, GxPal + ((e * 256) + i), pcol);
                i += 1;
            }
            emon.Port.CellsSet(gx, GxE(e, CsPal), 1);
            emon.Port.CellsSet(gx, GxE(e, CsNpal), 256);
            pcol = GxPalAt(gx, e, 255);
            emon.Port.CellsSet(gx, GxE(e, CsInit), pcol);
            return 1;
        }
        if (Pdfx.PxIs(ar, n0, Pdfxnames.PxDeviceN()) == 1) {
            el = Pdfx.PxNth(ar, h, 1);
            el = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
            if (el == 0) {
                return 0;
            }
            n = GxCount(ar, el);
            if ((n < 1) || (n > 32)) {
                return 0;
            }
            emon.Port.CellsSet(gx, GxE(e, CsKind), CkDevn);
            emon.Port.CellsSet(gx, GxE(e, CsNcomp), n);
            emon.Port.CellsSet(gx, GxE(e, CsClass), ClsSpot);
            // Every colorant /None: the space paints nothing.
            allnone = 1;
            rv = Pdflex.PlFirst(ar, el);
            while (rv != 0) {
                pcol = Pdfdoc.PdResolve(src, ar, dc, a, b, st, rv);
                if (Pdfx.PxIs(ar, pcol, Pdfxnames.PxNone()) == 0) {
                    allnone = 0;
                }
                rv = Pdflex.PlNext(ar, rv);
            }
            emon.Port.CellsSet(gx, GxE(e, CsNone), allnone);
            ok = GxTint(src, ar, dc, a, b, st, @out, gx, e, h, n);
            if (Pdfsrc.PsMissed(src)) {
                return 0;
            }
            if (ok == 1) {
                i = 0;
                while (i < n) {
                    Fx.FxPut(gx, GxIn + (2 * i), Fx.FxOne());
                    i += 1;
                }
                pcol = GxEntryRgb(gx, e, n);
                emon.Port.CellsSet(gx, GxE(e, CsInit), pcol);
            }
            return 1;
        }
        return 0;
    }
    public static int GxLookup(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells @out, emon.Port.Cells gx, int key) {
        // The table entry for a colour-space key (`gx-key-of`): the permanent four by their negative keys, a cached
        // entry, or a new one parsed from the object. Answers -1 when the space is not one this module reads (the
        // colour is then unknown) or the source missed.
        if (key == 0) {
            return -1;
        }
        if (key < 0) {
            return (0 - key) - 1;
        }
        int e = GxFind(gx, key);
        int okp = 0;
        if (e >= 0) {
            if (GxKind(gx, e) == 0) {
                return -1;
            }
            return e;
        }
        e = GxAlloc(gx, key);
        okp = GxParse(src, ar, dc, a, b, st, @out, gx, e, key);
        if (Pdfsrc.PsMissed(src)) {
            emon.Port.CellsSet(gx, GxE(e, CsKey), 0);
            return -1;
        }
        if (okp == 0) {
            emon.Port.CellsSet(gx, GxE(e, CsKind), 0);
            return -1;
        }
        return e;
    }
    internal static int GxOcSet(emon.Port.Cells gx, int num, int state) {
        // Record the state of OCG object `num`: the last one stated wins.
        int n = emon.Port.CellsAt(gx, GxOcn);
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(gx, GxOc + (2 * i)) == num) {
                emon.Port.CellsSet(gx, GxOc + ((2 * i) + 1), state);
                return 0;
            }
            i += 1;
        }
        if (n >= GxOcmax) {
            return 1;
        }
        emon.Port.CellsSet(gx, GxOc + (2 * n), num);
        emon.Port.CellsSet(gx, GxOc + ((2 * n) + 1), state);
        emon.Port.CellsSet(gx, GxOcn, n + 1);
        return 0;
    }
    internal static int GxOcGet(emon.Port.Cells gx, int num) {
        // The state of OCG object `num`: as stated, else the document's base state.
        int n = emon.Port.CellsAt(gx, GxOcn);
        int i = 0;
        while (i < n) {
            if (emon.Port.CellsAt(gx, GxOc + (2 * i)) == num) {
                return emon.Port.CellsAt(gx, GxOc + ((2 * i) + 1));
            }
            i += 1;
        }
        return emon.Port.CellsAt(gx, GxOcbase);
    }
    public static int GxOcRead(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells gx) {
        // Read the document's optional-content configuration once: `/Root /OCProperties /D` (SPEC 8.4.3's "default
        // state"): `/BaseState`, the `/ON` and `/OFF` arrays, then the `/AS` auto states for the `View` event.
        if (emon.Port.CellsAt(gx, GxOcread) == 1) {
            return 0;
        }
        emon.Port.CellsSet(gx, GxOcread, 1);
        emon.Port.CellsSet(gx, GxOcbase, 1);
        emon.Port.CellsSet(gx, GxOcn, 0);
        int root = Pdfdoc.PdRoot(dc);
        int ocp = Pdfx.PxDget(src, ar, dc, a, b, st, root, Pdfxnames.PxOcProperties());
        int d = 0;
        int arr = 0;
        int el = 0;
        int v = 0;
        int ev = 0;
        int cat = 0;
        int isview = 0;
        int ce = 0;
        int ocgs = 0;
        int oe = 0;
        int od = 0;
        int us = 0;
        int vw = 0;
        int vs = 0;
        if (ocp == 0) {
            return 0;
        }
        d = Pdfx.PxDget(src, ar, dc, a, b, st, ocp, Pdfxnames.PxD());
        if (d == 0) {
            return 0;
        }
        v = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxBaseState());
        if (Pdfx.PxIs(ar, v, Pdfxnames.PxOffUpper()) == 1) {
            emon.Port.CellsSet(gx, GxOcbase, 0);
        }
        arr = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxOnUpper());
        if (GxCount(ar, arr) != 0) {
            el = Pdflex.PlFirst(ar, arr);
            while (el != 0) {
                if (Pdflex.PlKindOf(ar, el) == 9) {
                    GxOcSet(gx, Pdflex.PlIntValue(ar, el), 1);
                }
                el = Pdflex.PlNext(ar, el);
            }
        }
        arr = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxOffUpper());
        if (GxCount(ar, arr) != 0) {
            el = Pdflex.PlFirst(ar, arr);
            while (el != 0) {
                if (Pdflex.PlKindOf(ar, el) == 9) {
                    GxOcSet(gx, Pdflex.PlIntValue(ar, el), 0);
                }
                el = Pdflex.PlNext(ar, el);
            }
        }
        // /AS: [<< /Event /View /Category [/View] /OCGs [...] >> ...]: an OCG whose /Usage /View /ViewState says
        // so is on or off while viewing.
        arr = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxAs());
        if (GxCount(ar, arr) != 0) {
            el = Pdflex.PlFirst(ar, arr);
            while (el != 0) {
                v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
                if ((v != 0) && (Pdflex.PlKindOf(ar, v) == 7)) {
                    ev = Pdfx.PxDget(src, ar, dc, a, b, st, v, Pdfxnames.PxEvent());
                    isview = 0;
                    if (Pdfx.PxIs(ar, ev, Pdfxnames.PxView()) == 1) {
                        isview = 1;
                    }
                    // A category that is stated must name View.
                    cat = Pdfx.PxDget(src, ar, dc, a, b, st, v, Pdfxnames.PxCategory());
                    if (GxCount(ar, cat) != 0) {
                        isview = 0;
                        if (Pdfx.PxIs(ar, ev, Pdfxnames.PxView()) == 1) {
                            ce = Pdflex.PlFirst(ar, cat);
                            while (ce != 0) {
                                vw = Pdfdoc.PdResolve(src, ar, dc, a, b, st, ce);
                                if (Pdfx.PxIs(ar, vw, Pdfxnames.PxView()) == 1) {
                                    isview = 1;
                                }
                                ce = Pdflex.PlNext(ar, ce);
                            }
                        }
                    }
                    if (isview == 1) {
                        ocgs = Pdfx.PxDget(src, ar, dc, a, b, st, v, Pdfxnames.PxOcgs());
                        if (GxCount(ar, ocgs) != 0) {
                            oe = Pdflex.PlFirst(ar, ocgs);
                            while (oe != 0) {
                                if (Pdflex.PlKindOf(ar, oe) == 9) {
                                    od = Pdfdoc.PdResolve(src, ar, dc, a, b, st, oe);
                                    us = Pdfx.PxDget(src, ar, dc, a, b, st, od, Pdfxnames.PxUsage());
                                    vw = Pdfx.PxDget(src, ar, dc, a, b, st, us, Pdfxnames.PxView());
                                    vs = Pdfx.PxDget(src, ar, dc, a, b, st, vw, Pdfxnames.PxViewState());
                                    if (Pdfx.PxIs(ar, vs, Pdfxnames.PxOffUpper()) == 1) {
                                        GxOcSet(gx, Pdflex.PlIntValue(ar, oe), 2);
                                    }
                                    if (Pdfx.PxIs(ar, vs, Pdfxnames.PxOnUpper()) == 1) {
                                        GxOcSet(gx, Pdflex.PlIntValue(ar, oe), 1);
                                    }
                                }
                                oe = Pdflex.PlNext(ar, oe);
                            }
                        }
                    }
                }
                el = Pdflex.PlNext(ar, el);
            }
        }
        return 0;
    }
    public static int GxOcState(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells gx, int raw, int depth) {
        // Whether the optional-content group or membership dictionary `raw` (a reference, usually) is on: 1 on, 0 off, and for
        // a group that the configuration leaves on but whose /Usage /View /ViewState says OFF (an /AS auto state) 2: the
        // readers that draw pages (poppler, Ghostscript, pdf.js) show it, Acrobat's View event hides it, so it is not "off".
        // A group that cannot be read is on (the document's content is not hidden by damage). An OCMD is on by its
        // `/VE` expression when it has one, else by its `/P` policy over its `/OCGs` (AnyOn is the default).
        if (raw == 0) {
            return 1;
        }
        int num = 0;
        int d = Pdfdoc.PdResolve(src, ar, dc, a, b, st, raw);
        int ty = 0;
        int ve = 0;
        int pol = 0;
        int members = 0;
        int el = 0;
        int n = 0;
        int non = 0;
        int noff = 0;
        int sd = 0;
        int stt = 0;
        if (Pdflex.PlKindOf(ar, raw) == 9) {
            num = Pdflex.PlIntValue(ar, raw);
        }
        if (d == 0) {
            return 1;
        }
        if (Pdflex.PlKindOf(ar, d) != 7) {
            return 1;
        }
        ty = Pdfdoc.PdDget(src, ar, dc, a, b, st, d, Pdfnames.PnType());
        if (Pdfx.PxIs(ar, ty, Pdfxnames.PxOcmd()) == 1) {
            if (depth > 8) {
                return 1;
            }
            ve = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxVe());
            if (GxCount(ar, ve) != 0) {
                return GxOcVe(src, ar, dc, a, b, st, gx, ve, depth);
            }
            pol = Pdfx.PxDget(src, ar, dc, a, b, st, d, Pdfxnames.PxP());
            members = Pdfx.PxGet(ar, d, Pdfxnames.PxOcgs());
            if (members == 0) {
                return 1;
            }
            sd = Pdfdoc.PdResolve(src, ar, dc, a, b, st, members);
            if (sd == 0) {
                return 1;
            }
            if (Pdflex.PlKindOf(ar, sd) == 7) {
                stt = GxOcState(src, ar, dc, a, b, st, gx, members, depth + 1);
                n = 1;
                if (stt != 0) {
                    non = 1;
                } else {
                    noff = 1;
                }
            }
            if (Pdflex.PlKindOf(ar, sd) == 6) {
                el = Pdflex.PlFirst(ar, sd);
                while (el != 0) {
                    stt = GxOcState(src, ar, dc, a, b, st, gx, el, depth + 1);
                    n += 1;
                    if (stt != 0) {
                        non += 1;
                    } else {
                        noff += 1;
                    }
                    el = Pdflex.PlNext(ar, el);
                }
            }
            if (n == 0) {
                return 1;
            }
            if (Pdfx.PxIs(ar, pol, Pdfxnames.PxAllOn()) == 1) {
                if (noff == 0) {
                    return 1;
                }
                return 0;
            }
            if (Pdfx.PxIs(ar, pol, Pdfxnames.PxAnyOff()) == 1) {
                if (noff > 0) {
                    return 1;
                }
                return 0;
            }
            if (Pdfx.PxIs(ar, pol, Pdfxnames.PxAllOff()) == 1) {
                if (non == 0) {
                    return 1;
                }
                return 0;
            }
            if (non > 0) {
                return 1;
            }
            return 0;
        }
        if (num == 0) {
            return emon.Port.CellsAt(gx, GxOcbase);
        }
        return GxOcGet(gx, num);
    }
    internal static int GxOcVe(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells gx, int arr, int depth) {
        // A visibility expression: [/And x ...], [/Or x ...], [/Not x], x an OCG or a nested expression.
        if (depth > 8) {
            return 1;
        }
        int opf = Pdflex.PlFirst(ar, arr);
        int opn = Pdfdoc.PdResolve(src, ar, dc, a, b, st, opf);
        int el = 0;
        int sd = 0;
        int v = 0;
        int acc = 0;
        int isand = 0;
        int isnot = 0;
        if (opn == 0) {
            return 1;
        }
        if (Pdfx.PxIs(ar, opn, Pdfxnames.PxAnd()) == 1) {
            isand = 1;
        }
        if (Pdfx.PxIs(ar, opn, Pdfxnames.PxNot()) == 1) {
            isnot = 1;
        }
        if ((isand == 0) && ((isnot == 0) && (Pdfx.PxIs(ar, opn, Pdfxnames.PxOr()) == 0))) {
            return 1;
        }
        if (isand == 1) {
            acc = 1;
        }
        el = Pdflex.PlNext(ar, opf);
        while (el != 0) {
            sd = Pdfdoc.PdResolve(src, ar, dc, a, b, st, el);
            v = 1;
            if ((sd != 0) && (Pdflex.PlKindOf(ar, sd) == 6)) {
                v = GxOcVe(src, ar, dc, a, b, st, gx, sd, depth + 1);
            } else {
                v = GxOcState(src, ar, dc, a, b, st, gx, el, depth + 1);
            }
            if (v != 0) {
                v = 1;
            }
            if (isnot == 1) {
                if (v == 1) {
                    return 0;
                }
                return 1;
            }
            if ((isand == 1) && (v == 0)) {
                acc = 0;
            }
            if ((isand == 0) && (v == 1)) {
                acc = 1;
            }
            el = Pdflex.PlNext(ar, el);
        }
        return acc;
    }
}
